      try { VORTEX.vortexOpenAndFill({ high: fz_h, low: fz_l, close: fz_c }, { timePeriod: optInTimePeriod, core: c2, outPlusVi: f0, outMinusVi: f0 }); fillOk = false; } catch (e) { svRejected(e); }
