    let codeF = '';
    try { ACCBANDS.accbandsOpen({ high: inHigh.slice(0, m), low: inLow.slice(0, m), close: inClose.slice(0, m) }, { timePeriod: optInTimePeriod, core }); } catch (_e) { r.rcOpen = rideCode(_e); codeO = rideCodeName(_e); }
