    try { ACCBANDS.accbandsOpenAndFill({ high: inHigh.slice(0, m), low: inLow.slice(0, m), close: inClose.slice(0, m) }, { timePeriod: optInTimePeriod, core, outUpperBand: fb0, outMiddleBand: fb1, outLowerBand: fb2 }); } catch (_e) { r.rcFill = rideCode(_e); codeF = rideCodeName(_e); }
    const cmpO = r.rcOpen === r.rcBatch && codeO === codeB;
    if (cmpO) r.rej++;
