    const cmpO = r.rcOpen === r.rcBatch && codeO === codeB;
    if (cmpO) r.rej++;
    if (!cmpO) { r.ok = false; r.leg = r.rcOpen === r.rcBatch ? 4 : 3; }
    const cmpF = r.rcFill === r.rcBatch && codeF === codeB;
    if (cmpF) r.rej++;
